#!/usr/bin/env bash
set -euo pipefail

# License-clean synthetic test of the exact inner E2E script generated by
# e2e-test.sh. No Delphi/Wine/Docker/image/installer payload is used here.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TMP="$(mktemp -d)"
trap 'rm -rf -- "${TMP}"' EXIT
MOCK_BIN="${TMP}/bin"
mkdir -p "${MOCK_BIN}"

# Extract the quoted heredoc that is sent to the disposable container.
awk '
    /^cat > / && /<<\047EOF\047$/ { inside=1; next }
    inside && /^EOF$/ { exit }
    inside { print }
' "${SCRIPT_DIR}/e2e-test.sh" > "${TMP}/run_test.sh"
if [[ ! -s "${TMP}/run_test.sh" ]]; then
    echo "ERROR: could not extract generated container test script" >&2
    exit 1
fi
bash -n "${TMP}/run_test.sh"

cat > "${MOCK_BIN}/wine" <<'MOCK_WINE'
#!/usr/bin/env bash
set -euo pipefail
case "${1:-}" in
    IdrTestConsole.exe)
        if [[ "${FAKE_CASE}" == console_error ]]; then
            exit 37
        fi
        if [[ "${FAKE_CASE}" == console_no_marker ]]; then
            echo "Console exited without its completion marker"
        else
            echo "[IDR_FEATURE:done] console testcase completed"
        fi
        ;;
    IdrTestGui.exe)
        case "${FAKE_CASE}" in
            gui_error) exit 38 ;;
            gui_missing) : ;;
            gui_bad) printf 'incorrect completion\n' > idr_test_artifact.txt ;;
            *) printf 'Automated interaction successful.\n' > idr_test_artifact.txt ;;
        esac
        ;;
    *) : ;; # fake installer and uninstaller
esac
MOCK_WINE
chmod +x "${MOCK_BIN}/wine"

# Avoid host display services and 2-second setup sleeps in these pure mocks.
for cmd in Xvfb wineboot wineserver sleep; do
    printf '#!/bin/sh\nexit 0\n' > "${MOCK_BIN}/${cmd}"
    chmod +x "${MOCK_BIN}/${cmd}"
done

failures=0
run_case() {
    local label="$1" expected="$2" stale="${3:-false}"
    local prefix="${TMP}/${label}-prefix"
    local installed="${prefix}/drive_c/Program Files/IdrTestcase"
    local rc=0
    mkdir -p "${installed}"
    for binary in IdrTestGui.exe IdrTestConsole.exe unins000.exe; do
        printf 'placeholder executable for mock only\n' > "${installed}/${binary}"
    done
    if [[ "${stale}" == true ]]; then
        printf 'Automated interaction successful.\n' > "${installed}/idr_test_artifact.txt"
    fi
    if (
        cd "${TMP}"
        PATH="${MOCK_BIN}:${PATH}" \
          WINEPREFIX="${prefix}" APP_NAME="IdrTestcase" \
          INSTALLER_NAME="Synthetic-Setup.exe" FAKE_CASE="${label}" \
          bash "${TMP}/run_test.sh"
    ) > "${TMP}/${label}.log" 2>&1; then
        rc=0
    else
        rc=$?
    fi
    if [[ "${rc}" -ne "${expected}" ]]; then
        echo "FAIL ${label}: expected status ${expected}, got ${rc}" >&2
        cat "${TMP}/${label}.log" >&2
        failures=$((failures + 1))
    else
        echo "PASS ${label} (status ${rc})"
    fi
}

run_case console_error 37
run_case console_no_marker 1
run_case gui_error 38
run_case gui_missing 1 true
run_case gui_bad 1
run_case success 0

if [[ "${failures}" -ne 0 ]]; then
    echo "FAIL: ${failures} synthetic E2E contract checks" >&2
    exit 1
fi
echo "PASS: 6/6 synthetic E2E contract checks (NOT product qualification)"
